/// Placeholder: API keys will be stored encrypted in ./data (never OS keychain/global config in portable mode). pub trait Vault: Send+Sync { fn get(&self, key:&str)->Option<String>; fn set(&self, key:&str, value:String); } pub struct InMemoryVault{ store: std::sync::Mutex<std::collections::HashMap<String,String>> } impl InMemoryVault{ pub fn new()->Self{ Self{store:Default::default()} } } impl Vault for InMemoryVault{ fn get(&self,k:&str)->Option<String>{ self.store.lock().unwrap().get(k).cloned() } fn set(&self,k:&str,v:String){ self.store.lock().unwrap().insert(k.into(),v); } }
